@@ -32,0 +32,2 @@
+import jdk.internal.vm.Continuation;
+import jdk.internal.vm.ContinuationSupport;
@@ -130,1 +132,13 @@
-        return POOLING_DISABLED ? 0 : acquireFromCache(cacheOwner(thread));
+        if (POOLING_DISABLED) {
+            return 0;
+        }
+        if (ContinuationSupport.isSupported() && thread.isVirtual()) {
+            Continuation.pin();
+            try {
+                return acquireFromCache(JLA.currentCarrierThread());
+            } finally {
+                Continuation.unpin();
+            }
+        } else {
+            return acquireFromCache(thread);
+        }
@@ -150,1 +164,10 @@
-        releaseToCache(cacheOwner(thread), pool, usedSize);
+        if (ContinuationSupport.isSupported() && thread.isVirtual()) {
+            Continuation.pin();
+            try {
+                releaseToCache(JLA.currentCarrierThread(), pool, usedSize);
+            } finally {
+                Continuation.unpin();
+            }
+        } else {
+            releaseToCache(thread, pool, usedSize);
+        }
@@ -246,9 +269,0 @@
-    // A mounted virtual thread cannot migrate until its continuation yields.
-    // Callers use this carrier only in cache operations with no yield point.
-    // Hence, it is safe to assume we remain on the owner carrier thread during
-    // operations in this class.
-    @ForceInline
-    private static Thread cacheOwner(Thread thread) {
-        return thread.isVirtual() ? JLA.currentCarrierThread() : thread;
-    }
